// env var loader
// env.js sets the global `loader` to a base64-encoded `env = { ... }` config
// object. This script decodes it and exposes the config object as window.env.
(function () {
  const encoded = typeof loader !== 'undefined' ? loader : '';
  let decoded;
  try {
    const binary = atob(encoded);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    decoded = new TextDecoder('utf-8').decode(bytes);
  } catch (e) {
    decoded = '';
  }
  // decoded is an `env = { ... }` declaration. Remove comments and line
  // breaks, then evaluate and keep the resulting object on window.env.
  // NOTE: do NOT strip all whitespace (`/\s/g`) — it destroys spaces inside
  // quoted string values (e.g. MS OAuth scopes) which must be preserved.
  window.env = eval(
    decoded
      .replace(/\/\/\s.*$/gm, '')
      .replace(/\r?\n/g, '')
  );
})();
